alter table public.profiles enable row level security; alter table public.offers enable row level security; alter table public.connections enable row level security; alter table public.messages enable row level security; alter table public.deals enable row level security; alter table public.subscriptions enable row level security; alter table public.reviews enable row level security;
-- These policies are intentionally scoped. Drop/recreate only policies with our exact names, not other project policies.
do $$ begin
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='kl_profiles_read') then create policy kl_profiles_read on public.profiles for select to authenticated using (true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='kl_profiles_insert_own') then create policy kl_profiles_insert_own on public.profiles for insert to authenticated with check (auth.uid()=id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='kl_profiles_update_own') then create policy kl_profiles_update_own on public.profiles for update to authenticated using (auth.uid()=id) with check (auth.uid()=id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='offers' and policyname='kl_offers_read') then create policy kl_offers_read on public.offers for select to anon,authenticated using (status='active' or auth.uid()=owner_id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='offers' and policyname='kl_offers_insert_own') then create policy kl_offers_insert_own on public.offers for insert to authenticated with check(auth.uid()=owner_id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='offers' and policyname='kl_offers_update_own') then create policy kl_offers_update_own on public.offers for update to authenticated using(auth.uid()=owner_id) with check(auth.uid()=owner_id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='connections' and policyname='kl_connections_participants') then create policy kl_connections_participants on public.connections for select to authenticated using(auth.uid()=requester_id or auth.uid()=offer_owner_id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='connections' and policyname='kl_connections_requester_insert') then create policy kl_connections_requester_insert on public.connections for insert to authenticated with check(auth.uid()=requester_id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='connections' and policyname='kl_connections_participant_update') then create policy kl_connections_participant_update on public.connections for update to authenticated using(auth.uid()=requester_id or auth.uid()=offer_owner_id) with check(auth.uid()=requester_id or auth.uid()=offer_owner_id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='messages' and policyname='kl_messages_participants') then create policy kl_messages_participants on public.messages for select to authenticated using(exists(select 1 from public.connections c where c.id=connection_id and (auth.uid()=c.requester_id or auth.uid()=c.offer_owner_id))); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='messages' and policyname='kl_messages_insert_sender') then create policy kl_messages_insert_sender on public.messages for insert to authenticated with check(auth.uid()=sender_id and exists(select 1 from public.connections c where c.id=connection_id and c.status='accepted' and (auth.uid()=c.requester_id or auth.uid()=c.offer_owner_id)) and exists(select 1 from public.connections c where c.id=connection_id and (recipient_id=c.requester_id or recipient_id=c.offer_owner_id))); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='deals' and policyname='kl_deals_participants_read') then create policy kl_deals_participants_read on public.deals for select to authenticated using(auth.uid()=buyer_id or auth.uid()=seller_id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='deals' and policyname='kl_deals_participants_insert') then create policy kl_deals_participants_insert on public.deals for insert to authenticated with check((auth.uid()=buyer_id or auth.uid()=seller_id) and exists(select 1 from public.connections c where c.id=connection_id and c.status='accepted' and c.offer_id=offer_id and (auth.uid()=c.requester_id or auth.uid()=c.offer_owner_id))); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='subscriptions' and policyname='kl_subscriptions_read_own') then create policy kl_subscriptions_read_own on public.subscriptions for select to authenticated using(auth.uid()=user_id); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='subscriptions' and policyname='kl_subscriptions_request_own') then create policy kl_subscriptions_request_own on public.subscriptions for insert to authenticated with check(auth.uid()=user_id and status='pending'); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='reviews' and policyname='kl_reviews_read') then create policy kl_reviews_read on public.reviews for select to authenticated using(true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='reviews' and policyname='kl_reviews_insert') then create policy kl_reviews_insert on public.reviews for insert to authenticated with check(auth.uid()=reviewer_id and exists(select 1 from public.deals d where d.id=deal_id and d.status='completed' and (auth.uid()=d.buyer_id or auth.uid()=d.seller_id) and reviewed_user_id in (d.buyer_id,d.seller_id))); end if;
end $$;
-- No direct client update policy for subscriptions/deals; completion and activation must use controlled RPC/admin paths.
